# page titles "X — Dictum Global"
SUFFIX = ' — Dictum Global'

# Ukrainian → Latin for initials (en/tr)
TR_LAT = dict(zip('АБВГҐДЕЄЖЗИІЇЙКЛМНОПРСТУФХЦЧШЩЮЯ', ['A','B','V','H','G','D','E','Y','Z','Z','Y','I','Y','Y','K','L','M','N','O','P','R','S','T','U','F','K','T','C','S','S','Y','Y']))
TR_RU = {'І': 'И', 'Ї': 'И', 'Є': 'Е', 'Ґ': 'Г'}


def _tr_one(t, lang):
    i = IDX[lang]
    if t in D:
        return D[t][i]
    if t.endswith(SUFFIX) and t[:-len(SUFFIX)] in D:
        return D[t[:-len(SUFFIX)]][i] + SUFFIX
    m = re.fullmatch(r'(\d+) напрямів роботи', t)
    if m:
        return m.group(1) + {'en': ' areas of work', 'tr': ' çalışma alanı', 'ru': ' направлений работы'}[lang]
    m = re.fullmatch(r'(\d+) з (\d+)', t)
    if m:
        return m.group(1) + {'en': ' of ', 'tr': ' / ', 'ru': ' из '}[lang] + m.group(2)
    m = re.fullmatch(r'\[Текст відгуку клієнта — додайте реальну цитату від (.+)\]', t)
    if m:
        who = _tr_one(m.group(1), lang)
        return {'en': f'[Client review text — add a real quote from {who}]', 'tr': f'[Müvekkil yorumu — {who} şirketinden gerçek bir alıntı ekleyin]', 'ru': f'[Текст отзыва клиента — добавьте реальную цитату от {who}]'}[lang]
    if re.fullmatch(r'[А-ЯІЇЄҐ]{2}', t):
        return ''.join(TR_LAT.get(c, c) for c in t) if lang != 'ru' else ''.join(TR_RU.get(c, c) for c in t)
    return None


def translate(html, lang):
    if lang == 'uk':
        return html
    def text_node(m):
        raw = m.group(1)
        t = raw.strip()
        if not t or not re.search('[А-Яа-яІіЇїЄєҐґ]', t):
            return m.group(0)
        r = _tr_one(t, lang)
        if r is None:
            return m.group(0)
        lead = raw[:len(raw) - len(raw.lstrip())]
        trail = raw[len(raw.rstrip()):]
        return '>' + lead + r + trail + '<'
    html = re.sub(r'>([^<>]+)<', text_node, html)
    def attr(m):
        t = m.group(2)
        if not re.search('[А-Яа-яІіЇїЄєҐґ]', t):
            return m.group(0)
        r = _tr_one(t.strip(), lang)
        return m.group(0) if r is None else f'{m.group(1)}="{r}"'
    html = re.sub(r'\b(aria-label|alt|placeholder|content|title)="([^"]*)"', attr, html)
    return html
